# Partes articuladas da lebre e da tartaruga (coordenadas na imagem original 1600x893).
import math
def elip(cx,cy,rx,ry,n=20):
    return [(cx+rx*math.cos(2*math.pi*i/n), cy+ry*math.sin(2*math.pi*i/n)) for i in range(n)]
def circ_corte(cx,cy,r,xmax,ymax,n=48):
    pts=[]
    for i in range(n):
        a=2*math.pi*i/n; x=cx+r*math.cos(a); y=cy+r*math.sin(a)
        pts.append((min(x,xmax),min(y,ymax)))
    return pts
